try
{
    LocalTime time = LocalTime.parse( timeInput ) ;
}
catch ( DateTimeParseException e ) 
{
    …
}
</code></pre>
<p>… and:</p>
<pre class="lang-java prettyprint-override"><code>String dateInput = IO.readln( &quot;&quot;Enter Date (YYYY-MM-DD)&quot; ) ;
try
{
    LocalDate date = LocalTime.parse( dateInput ) ;
